  // ── Crypto steps ──
  "c.step1.t": { fr: "Choisissez votre crypto et réseau", en: "Choose your crypto and network" },
  "c.step1.d": { fr: "Sélectionnez la cryptomonnaie (USDT, BTC, TRX…) et le réseau. TRC20 est recommandé pour USDT : frais quasi nuls et confirmation en 1-2 minutes.", en: "Select the cryptocurrency (USDT, BTC, TRX…) and the network. TRC20 is recommended for USDT: near-zero fees and 1-2 minute confirmation." },
  "c.step1.tip": { fr: "Évitez ERC20 pour USDT — frais de gas très élevés.", en: "Avoid ERC20 for USDT — very high gas fees." },
  "c.step2.t": { fr: "Renseignez votre email", en: "Enter your email" },
  "c.step2.d": { fr: "Entrez votre adresse email pour recevoir la confirmation et le suivi de la transaction automatiquement.", en: "Enter your email address to automatically receive confirmation and transaction tracking." },
  "c.step3.t": { fr: "Copiez notre adresse wallet", en: "Copy our wallet address" },
  "c.step3.d": { fr: "Notre adresse de dépôt s'affiche. Copiez-la avec précision — une erreur peut faire perdre vos fonds définitivement.", en: "Our deposit address is shown. Copy it precisely — an error can permanently lose your funds." },
  "c.step3.tip": { fr: "Double-vérifiez les 4 premiers et 4 derniers caractères.", en: "Double-check the first 4 and last 4 characters." },
  "c.step4.t": { fr: "Envoyez vos cryptos + partagez le TxID", en: "Send your crypto + share the TxID" },
  "c.step4.d": { fr: "Effectuez le virement et partagez le hash de transaction (TxID) sur WhatsApp avec la capture de l'envoi.", en: "Make the transfer and share the transaction hash (TxID) on WhatsApp with the sending screenshot." },
  "c.step4.tip": { fr: "Le TxID est visible dans votre wallet sous 'Historique des transactions'.", en: "The TxID is visible in your wallet under 'Transaction history'." },
  "c.step5.t": { fr: "Recevez vos FCFA sur MoMo", en: "Receive your FCFA on MoMo" },
  "c.step5.d": { fr: "Après confirmation blockchain, nous virons le montant en FCFA. Délai total : 15 à 30 min. Taux garanti au moment de l'accord.", en: "After blockchain confirmation, we send the FCFA amount. Total time: 15 to 30 min. Rate guaranteed at the time of agreement." },
  "c.step5.tip": { fr: "BTC peut prendre jusqu'à 1h selon la congestion réseau.", en: "BTC can take up to 1h depending on network congestion." },

  // ── Crypto FAQ ──
  "c.faq1.q": { fr: "Quel est le taux USDT en FCFA aujourd'hui au Cameroun ?", en: "What is the USDT to FCFA rate today in Cameroon?" },
  "c.faq1.a": { fr: "Le taux USDT/FCFA est mis à jour en temps réel dans notre ticker en haut de page. Nous achetons à 580 FCFA/$ et vendons à 700 FCFA/$. Ce taux est garanti au moment de votre transaction, sans aucune commission cachée.", en: "The USDT/FCFA rate is updated in real time in our ticker at the top of the page. We buy at 580 FCFA/$ and sell at 700 FCFA/$. This rate is guaranteed at the time of your transaction, with no hidden fees." },
  "c.faq2.q": { fr: "Comment vendre ses crypto en FCFA au Cameroun sans arnaque ?", en: "How to sell crypto for FCFA in Cameroon without scams?" },
  "c.faq2.a": { fr: "Chreol Empire opère depuis 2012 à Douala. Processus sécurisé en 3 étapes : (1) envoyez vos crypto à notre adresse vérifiée, (2) partagez le TxID sur WhatsApp avec capture de l'envoi, (3) recevez votre FCFA sur MTN MoMo ou Orange Money sous 30 min post-confirmation blockchain.", en: "Chreol Empire has operated since 2012 in Douala. Secure 3-step process: (1) send your crypto to our verified address, (2) share the TxID on WhatsApp with the sending screenshot, (3) receive your FCFA on MTN MoMo or Orange Money within 30 min after blockchain confirmation." },
  "c.faq3.q": { fr: "Quelle blockchain utiliser pour envoyer de l'USDT au Cameroun ?", en: "Which blockchain to use to send USDT to Cameroon?" },
  "c.faq3.a": { fr: "TRC20 (réseau Tron) est recommandé : frais proches de zéro et confirmations en 1-2 minutes. BEP20 (BNB Chain) est aussi accepté. Évitez ERC20 pour l'USDT — les frais de gas Ethereum peuvent dépasser 10$.", en: "TRC20 (Tron network) is recommended: near-zero fees and 1-2 minute confirmations. BEP20 (BNB Chain) is also accepted. Avoid ERC20 for USDT — Ethereum gas fees can exceed $10." },
  "c.faq4.q": { fr: "Combien de temps pour recevoir son MoMo après vente crypto ?", en: "How long to receive MoMo after selling crypto?" },
  "c.faq4.a": { fr: "En général 15 à 30 minutes après la première confirmation blockchain. Pour BTC, jusqu'à 1 heure selon la congestion du réseau. Partagez votre TxID dès l'envoi pour que nous surveillions l'arrivée en temps réel.", en: "Usually 15 to 30 minutes after the first blockchain confirmation. For BTC, up to 1 hour depending on network congestion. Share your TxID as soon as you send so we can monitor the arrival in real time." },
  "c.guide_title": { fr: "Comment vendre / acheter de la crypto — Étape par étape", en: "How to sell / buy crypto — Step by step" },

