  "pp.guide_title":  { fr: "Comment vendre / acheter du solde PayPal — Étape par étape", en: "How to sell / buy PayPal balance — Step by step" },
  "pp.step1.t": { fr: "Choisissez l'opération — Vente ou Achat", en: "Choose the operation — Sell or Buy" },
  "pp.step1.d": { fr: "Vente : vous vendez votre solde PayPal contre FCFA (580 FCFA/€). Achat : vous achetez du solde PayPal avec vos FCFA (700 FCFA/€).", en: "Sell: you sell your PayPal balance for FCFA (580 FCFA/€). Buy: you buy PayPal balance with your FCFA (700 FCFA/€)." },
  "pp.step1.tip": { fr: "Votre compte PayPal doit être européen (France, Belgique, Suisse…).", en: "Your PayPal account must be European (France, Belgium, Switzerland…)." },
  "pp.step2.t": { fr: "Entrez le montant et votre email PayPal", en: "Enter the amount and your PayPal email" },
  "pp.step2.d": { fr: "Saisissez le montant, votre email de compte PayPal, votre numéro MoMo et votre email de contact pour la confirmation.", en: "Enter the amount, your PayPal account email, your MoMo number and your contact email for confirmation." },
  "pp.step3.t": { fr: "Confirmez via WhatsApp", en: "Confirm via WhatsApp" },
  "pp.step3.d": { fr: "Envoyez le message pré-rempli à notre agent. Il vous répond sous 15–30 min avec les instructions précises.", en: "Send the pre-filled message to our agent. They reply within 15–30 min with precise instructions." },
  "pp.step4.t": { fr: "Effectuez le transfert PayPal ou MoMo", en: "Make the PayPal or MoMo transfer" },
  "pp.step4.d": { fr: "Vente : envoyez le montant à notre compte PayPal communiqué, puis partagez la capture de confirmation. Achat : réglez via MoMo selon les instructions.", en: "Sell: send the amount to our provided PayPal account, then share the confirmation screenshot. Buy: pay via MoMo per the instructions." },
  "pp.step5.t": { fr: "Recevez vos FCFA ou votre solde PayPal", en: "Receive your FCFA or PayPal balance" },
  "pp.step5.d": { fr: "Après confirmation du transfert, les fonds sont envoyés dans les 15–30 minutes. Taux garanti au moment de la transaction.", en: "After transfer confirmation, funds are sent within 15–30 minutes. Rate guaranteed at the time of the transaction." },
  "pp.step5.tip": { fr: "Gardez la capture de confirmation PayPal jusqu'à réception des fonds.", en: "Keep the PayPal confirmation screenshot until you receive the funds." },
  "pp.faq1.q": { fr: "Comment vendre son solde PayPal en FCFA au Cameroun ?", en: "How to sell your PayPal balance for FCFA in Cameroon?" },
  "pp.faq1.a": { fr: "3 étapes simples : (1) envoyez le montant en € à notre compte PayPal communiqué sur WhatsApp, (2) partagez la capture de confirmation d'envoi, (3) recevez votre FCFA sur MTN MoMo ou Orange Money en moins de 30 minutes. Taux garanti au moment de la transaction.", en: "3 simple steps: (1) send the amount in € to our PayPal account provided on WhatsApp, (2) share the sending confirmation screenshot, (3) receive your FCFA on MTN MoMo or Orange Money in under 30 minutes. Rate guaranteed at the time of the transaction." },
  "pp.faq2.q": { fr: "Quel est le taux de change PayPal en FCFA en 2026 ?", en: "What is the PayPal to FCFA exchange rate in 2026?" },
  "pp.faq2.a": { fr: "Nous achetons votre solde PayPal à 580 FCFA par euro et vendons à 700 FCFA par euro. Ces taux sont mis à jour régulièrement selon le marché. Consultez notre ticker en haut de page pour le cours en temps réel.", en: "We buy your PayPal balance at 580 FCFA per euro and sell at 700 FCFA per euro. These rates are updated regularly based on the market. Check our ticker at the top of the page for the real-time rate." },
  "pp.faq3.q": { fr: "Peut-on acheter du solde PayPal avec Orange Money au Cameroun ?", en: "Can you buy PayPal balance with Orange Money in Cameroon?" },
  "pp.faq3.a": { fr: "Oui, minimum 3 500 FCFA (environ 5€). Payez via Orange Money, MTN MoMo ou Express Union et recevez le solde PayPal correspondant dans les 30 minutes. Votre compte PayPal doit être européen (France, Belgique, Suisse…).", en: "Yes, minimum 3,500 FCFA (about 5€). Pay via Orange Money, MTN MoMo or Express Union and receive the corresponding PayPal balance within 30 minutes. Your PayPal account must be European (France, Belgium, Switzerland…)." },
  "pp.faq4.q": { fr: "Chreol Empire travaille-t-il avec les comptes PayPal camerounais ?", en: "Does Chreol Empire work with Cameroonian PayPal accounts?" },
  "pp.faq4.a": { fr: "Non. Nous travaillons uniquement avec des comptes PayPal européens (France, Belgique, Italie, Espagne, Suisse…). Les comptes africains ou camerounais ne sont pas éligibles en raison des restrictions PayPal sur les transferts internationaux.", en: "No. We only work with European PayPal accounts (France, Belgium, Italy, Spain, Switzerland…). African or Cameroonian accounts are not eligible due to PayPal restrictions on international transfers." },

