  "cp.how_title":     { fr: "Comment ça marche ?", en: "How does it work?" },
  "cp.how_1":         { fr: "Remplissez le formulaire et vérifiez le calcul", en: "Fill out the form and check the calculation" },
  "cp.how_2":         { fr: "Cliquez sur Ajouter au panier ou WhatsApp", en: "Click Add to cart or WhatsApp" },
  "cp.how_3":         { fr: "Notre agent vérifie votre code coupon", en: "Our agent verifies your coupon code" },
  "cp.how_4":         { fr: "Recevez vos FCFA sur Mobile Money en quelques minutes", en: "Receive your FCFA on Mobile Money in minutes" },
  "cp.wa_start":      { fr: "Démarrer directement via WhatsApp", en: "Start directly via WhatsApp" },
  "cp.guide_title":   { fr: "Comment échanger un coupon PCS / Transcash — Étape par étape", en: "How to exchange a PCS / Transcash coupon — Step by step" },
  "cp.step1.t": { fr: "Sélectionnez le type de coupon", en: "Select the coupon type" },
  "cp.step1.d": { fr: "Choisissez entre PCS Mastercard (7% commission) ou Transcash (0% commission). Entrez la valeur en euros (minimum 20€).", en: "Choose between PCS Mastercard (7% fee) or Transcash (0% fee). Enter the value in euros (minimum 20€)." },
  "cp.step2.t": { fr: "Entrez le code du coupon", en: "Enter the coupon code" },
  "cp.step2.d": { fr: "PCS Mastercard : 10 caractères alphanumériques (ex: AB12345678). Transcash : 12 chiffres. Ne partagez jamais votre code avant d'avoir confirmé l'échange.", en: "PCS Mastercard: 10 alphanumeric characters (e.g. AB12345678). Transcash: 12 digits. Never share your code before confirming the exchange." },
  "cp.step2.tip": { fr: "Grattez délicatement la zone de sécurité pour révéler le code.", en: "Gently scratch the security area to reveal the code." },
  "cp.step3.t": { fr: "Renseignez vos coordonnées MoMo", en: "Enter your MoMo details" },
  "cp.step3.d": { fr: "Indiquez votre opérateur (MTN ou Orange), votre numéro, votre nom complet et votre email pour la confirmation.", en: "Provide your operator (MTN or Orange), your number, your full name and your email for confirmation." },
  "cp.step4.t": { fr: "Envoyez la demande via WhatsApp", en: "Send the request via WhatsApp" },
  "cp.step4.d": { fr: "Notre agent vérifie le code en temps réel. Le processus prend 5 à 15 minutes. Restez disponible sur WhatsApp pendant cette période.", en: "Our agent verifies the code in real time. The process takes 5 to 15 minutes. Stay available on WhatsApp during this period." },
  "cp.step4.tip": { fr: "Un coupon utilisé ou invalide sera détecté immédiatement — nous vous informerons sans délai.", en: "A used or invalid coupon will be detected immediately — we'll inform you without delay." },
  "cp.step5.t": { fr: "Recevez vos FCFA sur MoMo", en: "Receive your FCFA on MoMo" },
  "cp.step5.d": { fr: "Après validation du coupon, le montant net en FCFA est viré sur votre compte Mobile Money en moins de 15 minutes.", en: "After coupon validation, the net FCFA amount is transferred to your Mobile Money account in under 15 minutes." },
  "cp.step5.tip": { fr: "PCS 100€ → 93€ × 450 = 41 850 FCFA nets reçus.", en: "PCS 100€ → 93€ × 450 = 41,850 FCFA net received." },
  "cp.faq1.q": { fr: "Comment échanger un coupon Transcash en FCFA au Cameroun ?", en: "How to exchange a Transcash coupon for FCFA in Cameroon?" },
  "cp.faq1.a": { fr: "Envoyez votre code Transcash sur WhatsApp avec le montant en €. Nous vérifions le code et vous virons le FCFA équivalent au taux de 450 FCFA/€ sur MTN MoMo ou Orange Money en 15 minutes. Minimum 20€ par échange.", en: "Send your Transcash code on WhatsApp with the amount in €. We verify the code and transfer the equivalent FCFA at the rate of 450 FCFA/€ on MTN MoMo or Orange Money within 15 minutes. Minimum 20€ per exchange." },
  "cp.faq2.q": { fr: "Quel est le taux de change PCS Mastercard en FCFA ?", en: "What is the PCS Mastercard exchange rate in FCFA?" },
  "cp.faq2.a": { fr: "Le taux PCS Mastercard est de 450 FCFA/€ après déduction de la commission de 7%. Formule : (montant − 7%) × 450 FCFA. Exemple : coupon de 100€ → 93€ × 450 = 41 850 FCFA reçus sur votre Mobile Money.", en: "The PCS Mastercard rate is 450 FCFA/€ after deducting the 7% fee. Formula: (amount − 7%) × 450 FCFA. Example: 100€ coupon → 93€ × 450 = 41,850 FCFA received on your Mobile Money." },
  "cp.faq3.q": { fr: "Y a-t-il un minimum pour échanger un coupon au Cameroun ?", en: "Is there a minimum to exchange a coupon in Cameroon?" },
  "cp.faq3.a": { fr: "Oui, le minimum est de 20€ par transaction. Pas de maximum fixe — des conditions spéciales s'appliquent pour les gros montants (500€ et plus). Contactez-nous via WhatsApp pour les transactions importantes.", en: "Yes, the minimum is 20€ per transaction. No fixed maximum — special conditions apply for large amounts (500€ and above). Contact us via WhatsApp for large transactions." },
  "cp.faq4.q": { fr: "Comment recevoir son argent après échange de coupon PCS ?", en: "How to receive your money after a PCS coupon exchange?" },
  "cp.faq4.a": { fr: "Par MTN MoMo ou Orange Money dans les 15 à 30 minutes après vérification du code. Pour les montants supérieurs à 500€, un paiement en espèces à notre boutique Vallée 3, Deido, Douala est également possible.", en: "Via MTN MoMo or Orange Money within 15 to 30 minutes after code verification. For amounts over 500€, cash payment at our shop in Vallée 3, Deido, Douala is also available." },

